{"code": "import os

def find_valid_jpgs(directory):
    """Find files with valid JPEG header"""
    valid_files = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.jpg'):
                filepath = os.path.join(root, file)
                try:
                    with open(filepath, 'rb') as f:
                        header = f.read(2)
                        # JPEG files start with FF D8
                        if header == b'\xff\xd8':
                            valid_files.append(filepath)
                except:
                    pass

    return valid_files

train_dir = 'data_small/Training'
test_dir = 'data_small/Testing'

valid_train = find_valid_jpgs(train_dir)
valid_test = find_valid_jpgs(test_dir)

print(f"Valid training images: {len(valid_train)}")
print(f"Valid test images: {len(valid_test)}")

if valid_train:
    print(f"First valid: {valid_train[0]}")
    with open(valid_train[0], 'rb') as f:
        print(f"Size: {os.path.getsize(valid_train[0])} bytes")"}

